/** Integer minor units. The only interesting method is allocate(). */
public record Money(long minorUnits, Currency currency) {

    /** Split as evenly as possible, distributing the remainder one unit at a
     *  time from the front. 1000 pennies over 3 ways -> [334, 333, 333].
     *  The total is ALWAYS preserved, which is the entire contract. */
    public List<Money> allocate(int ways) {
        long base = minorUnits / ways;
        long remainder = minorUnits % ways;

        List<Money> out = new ArrayList<>(ways);
        for (int i = 0; i < ways; i++) {
            out.add(new Money(base + (i < remainder ? 1 : 0), currency));
        }
        return out;
    }
}

final class EqualSplit implements SplitStrategy {
    @Override
    public Map<User, Money> divide(Money total, List<User> users) {
        List<Money> parts = total.allocate(users.size());
        Map<User, Money> shares = new LinkedHashMap<>();
        for (int i = 0; i < users.size(); i++) shares.put(users.get(i), parts.get(i));
        return shares;
    }
}

final class ExactSplit implements SplitStrategy {
    private final Map<User, Money> exact;
    @Override
    public Map<User, Money> divide(Money total, List<User> users) {
        Money sum = exact.values().stream().reduce(Money.zero(), Money::plus);
        // Validate, loudly. A split that does not sum to the total is the
        // most common way a real expense app corrupts a group's balances.
        if (!sum.equals(total)) throw new IllegalArgumentException("shares must sum to the total");
        return exact;
    }
}

/** Net everyone out, then match biggest debtor to biggest creditor.
 *  Each step zeroes at least one person, so this terminates in <= n-1
 *  transfers. That bound is the thing worth saying out loud. */
List<Transfer> settle(Map<User, Money> net) {
    PriorityQueue<Entry> owes = new PriorityQueue<>(Comparator.comparingLong(Entry::amount));          // most negative
    PriorityQueue<Entry> owed = new PriorityQueue<>(Comparator.comparingLong(Entry::amount).reversed()); // most positive

    net.forEach((user, balance) -> {
        if (balance.minorUnits() < 0) owes.add(new Entry(user, balance.minorUnits()));
        else if (balance.minorUnits() > 0) owed.add(new Entry(user, balance.minorUnits()));
    });

    List<Transfer> transfers = new ArrayList<>();
    while (!owes.isEmpty() && !owed.isEmpty()) {
        Entry debtor = owes.poll(), creditor = owed.poll();
        long amount = Math.min(-debtor.amount(), creditor.amount());

        transfers.add(new Transfer(debtor.user(), creditor.user(), amount));

        long debtorLeft = debtor.amount() + amount;
        long creditorLeft = creditor.amount() - amount;
        if (debtorLeft < 0) owes.add(new Entry(debtor.user(), debtorLeft));
        if (creditorLeft > 0) owed.add(new Entry(creditor.user(), creditorLeft));
    }
    return transfers;
}
